using System;using System.Diagnostics;using System.IO;using System.Text;using System.Linq;using System.Windows.Forms;
internal static partial class AutoBackground{
 static DateTime launchAttempt;
 static string WorkerPathFile{get{return Path.Combine(Engine.Store,"background-worker.txt");}}
 static string HealthFile{get{return Path.Combine(Engine.Store,"background-service.txt");}}
 static string ActiveWorkerPath{get{try{return File.ReadAllText(WorkerPathFile).Trim();}catch{return Application.ExecutablePath;}}}
 static void SaveHealth(string state){try{var p=Process.GetCurrentProcess();string data=p.Id+"\n"+p.StartTime.ToUniversalTime().Ticks+"\n"+DateTime.UtcNow.Ticks+"\n"+Application.ExecutablePath+"\n"+state;string stage=HealthFile+".tmp";File.WriteAllText(stage,data,Encoding.UTF8);if(File.Exists(HealthFile))File.Replace(stage,HealthFile,null);else File.Move(stage,HealthFile);}catch{}}
 static bool ServiceAlive(bool currentVersion){try{var lines=File.ReadAllLines(HealthFile);if(lines.Length<5||DateTime.UtcNow.Ticks-long.Parse(lines[2])>TimeSpan.FromSeconds(lines[4].StartsWith("正在")?130:12).Ticks)return false;var p=Process.GetProcessById(int.Parse(lines[0]));return !p.HasExited&&p.StartTime.ToUniversalTime().Ticks==long.Parse(lines[1])&&(!currentVersion||String.Equals(lines[3],Application.ExecutablePath,StringComparison.OrdinalIgnoreCase));}catch{return false;}}
 public static string ServiceStatus{get{if(SessionExitRequested)return "本次已退出，开机启动设置保留；重新打开调色室或修复后台可恢复。";if(!Enabled)return "后台未启用：退出微信后，壁纸和文字效果不会自动恢复。";if(WeixinIdentity()==""&&MonitorAlive())return "监听器运行中，等待微信启动；主题后台尚未加载。";if(!ServiceAlive(false))return "已开启自动应用，但后台未响应；请点击「修复并启动后台」。";try{return "后台运行中 · "+File.ReadAllLines(HealthFile)[4]+"\n调色室窗口可以关闭，托盘服务会继续运行。";}catch{return "后台运行中。";}}}
 public static void EnsureStarted(){if(!Enabled||NativeBackground.InternalModulePresent())return;using(var key=Microsoft.Win32.Registry.CurrentUser.CreateSubKey(@"Software\Microsoft\Windows\CurrentVersion\Run"))key.SetValue("WeixinThemeStudioBackground","\""+Application.ExecutablePath+"\" --monitor");Directory.CreateDirectory(Engine.Store);File.WriteAllText(WorkerPathFile,Application.ExecutablePath);EnsureMonitor();EnsureThemeWorker();}
 internal static string ConfigurationKey(string source){return "engine=6.6|"+source+"|appearance="+AppearanceProfiles.Mode+"|theme="+(Engine.ActiveTheme==null?"original":Palette.Pack(Engine.ActiveTheme))+"|whole="+NativeBackground.WholeEnabled+"|strength="+NativeBackground.ImageStrength+"|uniform="+NativeBackground.UniformBackdrop+"|text="+NativeBackground.InkText+"|icons="+NativeBackground.InkIcons+"|icon-effects="+IconEffects.Load().Key+"|accent="+NativeBackground.InkAccent+"|link="+NativeBackground.InkLink+"|secondary="+NativeBackground.InkSecondary+"|canvas="+NativeBackground.InkCanvas+"|chat="+NativeBackground.InkChat+"|effects="+BackgroundEffects.Load().Key+"|inputBorder="+InputAppearance.Load().Key;}
}
internal static partial class NativeBackground{
 static void WriteSettingsSignature(byte[] bytes,string source,bool removing){if(removing)return;Encoding.ASCII.GetBytes("WXCFG001").CopyTo(bytes,0x7c000);Encoding.ASCII.GetBytes(Engine.Hash(Encoding.UTF8.GetBytes(AutoBackground.ConfigurationKey(source)))).CopyTo(bytes,0x7c008);}
 internal static bool RuntimeReady(string source){var processes=Process.GetProcessesByName("Weixin").Where(p=>p.MainWindowHandle!=IntPtr.Zero).ToArray();if(processes.Length!=1||cachedImageBase==0)return false;var h=OpenProcess(0x410,false,processes[0].Id);if(h==IntPtr.Zero)return false;try{long image=cachedImageBase;var call=Read(h,image+CallRva,5);if(call[0]!=0xe8)return false;long b=image+CallRva+5+BitConverter.ToInt32(call,1)-0x1000;if(Encoding.ASCII.GetString(Read(h,b,7))!="WXBG001"||Encoding.ASCII.GetString(Read(h,b+0x7c000,8))!="WXCFG001")return false;string expected=Engine.Hash(Encoding.UTF8.GetBytes(AutoBackground.ConfigurationKey(source)));if(Encoding.ASCII.GetString(Read(h,b+0x7c008,64))!=expected)return false;if((InkText!="original"||InkChat!="original"||InkLink!="original")&&Pointer(h,image+0x93ab420)!=b+0x36000)return false;if(IconsActive&&!Equal(Read(h,image+IconColorCall,5),Call(image+IconColorCall,b+0x70000)))return false;return InputRuntimeReady(h,image,b);}catch{return false;}finally{CloseHandle(h);}}
}


